import { Page } from '../src/types';
import fs from 'fs';
import path from 'path';
import os from 'os';

describe('generateSite', () => {
  let outputDir: string;

  beforeEach(() => {
    outputDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-test-'));
  });

  afterEach(() => {
    fs.rmSync(outputDir, { recursive: true, force: true });
  });

  const pages: Page[] = [
    {
