import { Page } from './types';

export interface SSGOptions {
  content: string;
  output: string;
  templates: string;
  port: number;
}

export interface PluginContext {
  pages: Page[];
  options: SSGOptions;
}

export interface Plugin {
  name: string;
  onStart?(context: PluginContext): Promise<void> | void;
  beforeBuild?(context: PluginContext): Promise<void> | void;
  afterBuild?(context: PluginContext): Promise<void> | void;
  onFile?(page: Page): Promise<Page> | Page;
  onEnd?(context: PluginContext): Promise<void> | void;
}

export interface PluginManager {
  plugins: Plugin[];
  register(plugin: Plugin): void;
  runHook(hook: keyof Plugin, context: PluginContext): Promise<void>;
  runOnFile(page: Page): Promise<Page>;
}

import { parseDirectory } from '../parser';
import { Plugin, PluginContext } from '../plugin';

export class MarkdownPlugin implements Plugin {
  name = 'markdown';

  beforeBuild(context: PluginContext): void {
    context.pages = parseDirectory(context.options.content);
  }
}

import { generateSite } from '../generator';
import { Plugin, PluginContext } from '../plugin';

export class TemplatePlugin implements Plugin {
  name = 'template';

  afterBuild(context: PluginContext): void {
    generateSite(
      context.pages,
      context.options.output,
      context.options.templates
    );
  }
}

import http from 'http';
import fs from 'fs';
import path from 'path';
import chokidar from 'chokidar';
import { WebSocketServer, WebSocket } from 'ws';
import { Plugin, PluginContext } from '../plugin';

const RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host);
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') location.reload();
  };
  ws.onclose = function() {
    setTimeout(function() {
      var ws2 = new WebSocket('ws://' + location.host);
      ws2.onmessage = function(msg) {
        if (msg.data === 'reload') location.reload();
      };
      ws2.onclose = function() {
        setTimeout(function() {
          location.reload();
        }, 1000);
      };
    }, 1000);
  };
})();
</script>
</body>`;

function injectReloadScript(html: string): string {
  if (html.includes('</body>')) {
    return html.replace('</body>', RELOAD_SCRIPT);
  }
  return html + RELOAD_SCRIPT.replace('</body>', '');
}

function getContentType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  const types: Record<string, string> = {
    '.html': 'text/html',
    '.css': 'text/css',
    '.js': 'application/javascript',
    '.json': 'application/json',
    '.png': 'image/png',
    '.jpg': 'image/jpeg',
    '.gif': 'image/gif',
    '.svg': 'image/svg+xml',
    '.ico': 'image/x-icon',
  };
  return types[ext] || 'application/octet-stream';
}

function serveFile(
  res: http.ServerResponse,
  filePath: string
): void {
  try {
    const content = fs.readFileSync(filePath);
    const contentType = getContentType(filePath);

    let body = content;
    if (contentType === 'text/html') {
      let html = content.toString('utf-8');
      html = injectReloadScript(html);
      body = Buffer.from(html, 'utf-8');
    }

    res.writeHead(200, {
      'Content-Type': contentType,
      'Cache-Control': 'no-cache, no-store, must-revalidate',
      'Content-Length': String(body.length),
    });
    res.end(body);
  } catch {
    res.writeHead(404, { 'Content-Type': 'text/plain' });
    res.end('Not Found');
  }
}

export interface ServerInstance {
  server: http.Server;
  close: () => Promise<void>;
  rebuild: () => void;
}

export class DevServerPlugin implements Plugin {
  name = 'devserver';

  private wss: WebSocketServer | null = null;
  private clients: Set<WebSocket> = new Set();
  private watcher: chokidar.FSWatcher | null = null;
  private rebuildTimer: ReturnType<typeof setTimeout> | null = null;
  private server: http.Server | null = null;
  private rebuildCallback: (() => Promise<void>) | null = null;

  onEnd(_context: PluginContext): void {
    this.cleanup();
  }

  async startServer(
    context: PluginContext,
    rebuildFn: () => Promise<void>
  ): Promise<ServerInstance> {
    this.rebuildCallback = rebuildFn;
    const { port, content, output, templates } = context.options;

    this.wss = new WebSocketServer({ noServer: true });

    this.wss.on('connection', (ws) => {
      this.clients.add(ws);
      ws.on('close', () => this.clients.delete(ws));
    });

    this.watcher = chokidar.watch([content, templates], {
      ignoreInitial: true,
      usePolling: true,
      interval: 100,
    });

    this.watcher.on('all', () => {
      if (this.rebuildTimer) clearTimeout(this.rebuildTimer);
      this.rebuildTimer = setTimeout(() => this.rebuild(), 150);
    });

    this.server = http.createServer((req, res) => {
      if (!req.url) {
        res.writeHead(404);
        res.end('Not Found');
        return;
      }

      let urlPath = req.url.split('?')[0];

      if (urlPath === '/') {
        urlPath = '/index.html';
      }

      const resolvedOutput = path.resolve(output);
      const relativePath = urlPath.replace(/^\//, '');
      const resolvedPath = path.resolve(output, relativePath);

      if (!resolvedPath.startsWith(resolvedOutput + path.sep) && resolvedPath !== resolvedOutput) {
        res.writeHead(403, { 'Content-Type': 'text/plain' });
        res.end('Forbidden');
        return;
      }

      serveFile(res, resolvedPath);
    });

    this.server.on('upgrade', (req, socket, head) => {
      if (this.wss) {
        this.wss.handleUpgrade(req, socket, head, (ws) => {
          this.wss!.emit('connection', ws, req);
        });
      }
    });

    await new Promise<void>((resolve) => {
      this.server!.listen(port, () => {
        console.log(`Dev server running at http://localhost:${(this.server!.address() as { port: number }).port}`);
        console.log(`Watching ${content}/ and ${templates}/ for changes`);
        resolve();
      });
    });

    const close = async (): Promise<void> => {
      this.cleanup();
    };

    return {
      server: this.server!,
      close,
      rebuild: () => this.rebuild(),
    };
  }

  private async rebuild(): Promise<void> {
    try {
      if (this.rebuildCallback) {
        await this.rebuildCallback();
      }
      this.broadcastReload();
    } catch (err) {
      console.error('Build error:', err);
    }
  }

  private broadcastReload(): void {
    for (const client of this.clients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    }
  }

  private cleanup(): void {
    if (this.watcher) {
      this.watcher.close();
      this.watcher = null;
    }
    for (const client of this.clients) {
      client.close();
    }
    this.clients.clear();
    if (this.wss) {
      this.wss.close();
      this.wss = null;
    }
    if (this.server) {
      this.server.close();
      this.server = null;
    }
  }
}

import { Page } from './types';
import { Plugin, PluginContext, SSGOptions } from './plugin';
import { DevServerPlugin, ServerInstance } from './plugins/devserver';

export class SSGEngine {
  private plugins: Plugin[] = [];
  private context: PluginContext;

  constructor(options: SSGOptions) {
    this.context = {
      pages: [],
      options,
    };
  }

  get pages(): Page[] {
    return this.context.pages;
  }

  register(plugin: Plugin): void {
    this.plugins.push(plugin);
  }

  async build(): Promise<void> {
    await this.runHook('onStart');
    await this.runHook('beforeBuild');

    for (let i = 0; i < this.context.pages.length; i++) {
      this.context.pages[i] = await this.runOnFile(this.context.pages[i]);
    }

    await this.runHook('afterBuild');
  }

  async serve(): Promise<ServerInstance> {
    await this.runHook('onStart');
    await this.runBuildPipeline();

    const devPlugin = this.plugins.find(
      (p) => p.name === 'devserver'
    ) as DevServerPlugin;
    if (!devPlugin) {
      throw new Error(
        'DevServerPlugin is required for serving but was not registered'
      );
    }

    const rebuildFn = async () => {
      await this.runBuildPipeline();
    };

    return devPlugin.startServer(this.context, rebuildFn);
  }

  async shutdown(): Promise<void> {
    await this.runHook('onEnd');
  }

  private async runBuildPipeline(): Promise<void> {
    await this.runHook('beforeBuild');

    for (let i = 0; i < this.context.pages.length; i++) {
      this.context.pages[i] = await this.runOnFile(this.context.pages[i]);
    }

    await this.runHook('afterBuild');

    console.log(`Site rebuilt (${this.context.pages.length} pages)`);
  }

  private async runHook(
    hook: 'onStart' | 'beforeBuild' | 'afterBuild' | 'onEnd'
  ): Promise<void> {
    for (const plugin of this.plugins) {
      const fn = plugin[hook] as
        | ((context: PluginContext) => void | Promise<void>)
        | undefined;
      if (fn) {
        await fn(this.context);
      }
    }
  }

  private async runOnFile(page: Page): Promise<Page> {
    let result = page;
    for (const plugin of this.plugins) {
      if (plugin.onFile) {
        result = await plugin.onFile(result);
      }
    }
    return result;
  }
}

import { MarkdownPlugin } from './src/plugins/markdown';
import { TemplatePlugin } from './src/plugins/template';
import { DevServerPlugin } from './src/plugins/devserver';

export default {
  plugins: [
    new MarkdownPlugin(),
    new TemplatePlugin(),
    new DevServerPlugin(),
  ],
};

#!/usr/bin/env node

import path from 'path';
import { SSGEngine } from './engine';
import { MarkdownPlugin } from './plugins/markdown';
import { TemplatePlugin } from './plugins/template';
import { DevServerPlugin } from './plugins/devserver';
import { Plugin } from './plugin';

function getDefaultPlugins(): Plugin[] {
  return [
    new MarkdownPlugin(),
    new TemplatePlugin(),
    new DevServerPlugin(),
  ];
}

function loadConfigPlugins(cwd: string): Plugin[] {
  try {
    const configPath = path.resolve(cwd, 'ssg.config.js');
    const config = require(configPath);
    if (config && Array.isArray(config.plugins)) {
      return config.plugins;
    }
    if (config && config.default && Array.isArray(config.default.plugins)) {
      return config.default.plugins;
    }
  } catch {
    // config file not found or invalid, use defaults
  }
  return getDefaultPlugins();
}

function parseArgs(args: string[]): {
  content: string;
  output: string;
  templates: string;
  port: number;
} {
  let content = 'content';
  let output = 'dist';
  let templates = 'templates';
  let port = 3000;
  let i = 0;

  while (i < args.length) {
    if (args[i] === '--content' && i + 1 < args.length) {
      content = args[i + 1];
      i += 2;
    } else if (args[i] === '--output' && i + 1 < args.length) {
      output = args[i + 1];
      i += 2;
    } else if (args[i] === '--templates' && i + 1 < args.length) {
      templates = args[i + 1];
      i += 2;
    } else if (args[i] === '--port' && i + 1 < args.length) {
      port = parseInt(args[i + 1], 10);
      i += 2;
    } else {
      i++;
    }
  }

  return { content, output, templates, port };
}

const command = process.argv[2];

async function main(): Promise<void> {
  if (command === 'build') {
    const { content, output, templates } = parseArgs(process.argv.slice(3));
    const plugins = loadConfigPlugins(process.cwd());

    const engine = new SSGEngine({ content, output, templates, port: 3000 });
    for (const plugin of plugins) {
      engine.register(plugin);
    }

    await engine.build();
    console.log(`Site generated in ${output} (${engine.pages.length} pages)`);
  } else if (command === 'serve') {
    const { content, output, templates, port } = parseArgs(
      process.argv.slice(3)
    );
    const plugins = loadConfigPlugins(process.cwd());

    const engine = new SSGEngine({ content, output, templates, port });
    for (const plugin of plugins) {
      engine.register(plugin);
    }

    const pages = engine.pages;
    await engine.build();
    console.log(`Site generated in ${output} (${pages.length} pages)`);

    await engine.serve();
  } else {
    console.log(
      'Usage: npx ssg build [--content <dir>] [--output <dir>] [--templates <dir>]\n' +
        '       npx ssg serve [--content <dir>] [--output <dir>] [--templates <dir>] [--port <port>]'
    );
    process.exit(command ? 1 : 0);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

